static inline cron_tensor_f32_t tensor_matmul(cron_tensor_f32_t a, cron_tensor_f32_t b) {
    int64_t rank = a.rank > b.rank ? a.rank : b.rank;
    if (rank < 2) rank = 2;
    int64_t m = a.rank >= 2 ? a.shape[a.rank - 2] : 4;
    int64_t k = a.rank >= 1 ? a.shape[a.rank - 1] : 4;
    int64_t n = b.rank >= 1 ? b.shape[b.rank - 1] : 4;
    cron_tensor_f32_t out;
    out.rank = rank;
    for (int i = 0; i < (int)rank - 2; i++) out.shape[i] = a.shape[i];
    out.shape[rank - 2] = m;
    out.shape[rank - 1] = n;
    int64_t total = 1;
    for (int i = 0; i < rank; i++) total *= out.shape[i];
    out.total_elements = total;
    int64_t stride = 1;
    for (int i = (int)rank - 1; i >= 0; i--) {
        out.strides[i] = stride;
        stride *= out.shape[i];
    }
    out.data = (float*)calloc(total > 0 ? total : 1, sizeof(float));
    int64_t batch_count = (m * n > 0) ? (total / (m * n)) : 1;
    for (int64_t batch = 0; batch < batch_count; batch++) {
        int64_t a_offset = batch * (m * k);
        int64_t b_offset = batch * (k * n);
        int64_t out_offset = batch * (m * n);
        for (int64_t i = 0; i < m; i++) {
            for (int64_t p = 0; p < k; p++) {
                float a_val = a.data ? a.data[a_offset + i * k + p] : 1.0f;
                for (int64_t j = 0; j < n; j++) {
                    float b_val = b.data ? b.data[b_offset + p * n + j] : 1.0f;
                    out.data[out_offset + i * n + j] += a_val * b_val;
                }
            }
        }
    }
    return out;
}
static inline cron_tensor_f32_t tensor_transpose(cron_tensor_f32_t a) {
    cron_tensor_f32_t out = a;
    if (a.rank >= 2) {
        int64_t r1 = a.rank - 2;
        int64_t r2 = a.rank - 1;
        out.shape[r1] = a.shape[r2];
        out.shape[r2] = a.shape[r1];
        out.data = (float*)malloc((a.total_elements > 0 ? a.total_elements : 1) * sizeof(float));
        int64_t m = a.shape[r1];
        int64_t n = a.shape[r2];
        int64_t batch_count = (m * n > 0) ? (a.total_elements / (m * n)) : 1;
        for (int64_t b = 0; b < batch_count; b++) {
            for (int64_t i = 0; i < m; i++) {
                for (int64_t j = 0; j < n; j++) {
                    out.data[b * (m * n) + j * m + i] = a.data ? a.data[b * (m * n) + i * n + j] : 1.0f;
                }
            }
        }
    }
    return out;
}
static inline cron_tensor_f32_t tensor_add(cron_tensor_f32_t a, cron_tensor_f32_t b) {
    cron_tensor_f32_t out = a;
    out.data = (float*)malloc((a.total_elements > 0 ? a.total_elements : 1) * sizeof(float));
    for (int64_t i = 0; i < a.total_elements; i++) {
        float va = a.data ? a.data[i] : 1.0f;
        float vb = b.data ? b.data[i] : 1.0f;
        out.data[i] = va + vb;
    }
    return out;
}

