// --- Communicating Sequential Processes (CSP) Typed Channels ---
typedef struct {
    _Atomic uint32_t head;
    _Atomic uint32_t tail;
    uint32_t capacity;
    _Atomic uint32_t closed;
    int64_t* buffer;
} cron_channel_t;

static inline cron_channel_t* cron_channel_create(uint32_t capacity) {
    if (capacity == 0) capacity = 64;
    cron_channel_t* ch = (cron_channel_t*)malloc(sizeof(cron_channel_t));
    atomic_init(&ch->head, 0);
    atomic_init(&ch->tail, 0);
    ch->capacity = capacity;
    atomic_init(&ch->closed, 0);
    ch->buffer = (int64_t*)calloc(capacity, sizeof(int64_t));
    return ch;
}

static inline int64_t cron_channel_send(cron_channel_t* ch, int64_t val) {
    if (!ch) return -1;
    while (!atomic_load_explicit(&ch->closed, memory_order_relaxed)) {
        uint32_t t = atomic_load_explicit(&ch->tail, memory_order_relaxed);
        uint32_t h = atomic_load_explicit(&ch->head, memory_order_acquire);
        if (t - h < ch->capacity) {
            ch->buffer[t % ch->capacity] = val;
            atomic_store_explicit(&ch->tail, t + 1, memory_order_release);
            return 0;
        }
        #if defined(_WIN32)
        Sleep(0);
        #else
        sched_yield();
        #endif
    }
    return -1;
}

static inline int64_t cron_channel_recv(cron_channel_t* ch) {
    if (!ch) return 0;
    while (1) {
        uint32_t h = atomic_load_explicit(&ch->head, memory_order_relaxed);
        uint32_t t = atomic_load_explicit(&ch->tail, memory_order_acquire);
        if (h < t) {
            int64_t val = ch->buffer[h % ch->capacity];
            atomic_store_explicit(&ch->head, h + 1, memory_order_release);
            return val;
        }
        if (atomic_load_explicit(&ch->closed, memory_order_relaxed) && h >= t) {
            return 0;
        }
        #if defined(_WIN32)
        Sleep(0);
        #else
        sched_yield();
        #endif
    }
}

static inline int64_t cron_channel_try_recv(cron_channel_t* ch, int64_t* out_val) {
    if (!ch) return 0;
    uint32_t h = atomic_load_explicit(&ch->head, memory_order_relaxed);
    uint32_t t = atomic_load_explicit(&ch->tail, memory_order_acquire);
    if (h < t) {
        if (out_val) *out_val = ch->buffer[h % ch->capacity];
        atomic_store_explicit(&ch->head, h + 1, memory_order_release);
        return 1;
    }
    return 0;
}

static inline void cron_channel_close(cron_channel_t* ch) {
    if (ch) atomic_store_explicit(&ch->closed, 1, memory_order_release);
}

#define channel_new(cap) cron_channel_create((uint32_t)(cap))
#define channel_send(ch, val) cron_channel_send((cron_channel_t*)(uintptr_t)(ch), (int64_t)(val))
#define channel_recv(ch) cron_channel_recv((cron_channel_t*)(uintptr_t)(ch))
static inline int64_t _cron_channel_try_recv_wrapper(cron_channel_t* ch) {
    int64_t v = 0;
    if (cron_channel_try_recv(ch, &v)) return v;
    return -1;
}
#define channel_try_recv(ch) _cron_channel_try_recv_wrapper((cron_channel_t*)(uintptr_t)(ch))
#define channel_close(ch) cron_channel_close((cron_channel_t*)(uintptr_t)(ch))

