static inline int64_t torus_distance(uint32_t c1, uint32_t c2) {
    int dx = abs((int)(c1 % 4) - (int)(c2 % 4)); if (dx > 2) dx = 4 - dx;
    int dy = abs((int)((c1 / 4) % 4) - (int)((c2 / 4) % 4)); if (dy > 2) dy = 4 - dy;
    int dz = abs((int)((c1 / 16) % 4) - (int)((c2 / 16) % 4)); if (dz > 2) dz = 4 - dz;
    int dw = abs((int)((c1 / 64) % 4) - (int)((c2 / 64) % 4)); if (dw > 2) dw = 4 - dw;
    return dx + dy + dz + dw;
}
