// --- 256-Core Neuromorphic Fiber / Thread Runtime ---
typedef struct {
    #if defined(_WIN32)
    HANDLE thread;
    #else
    pthread_t thread;
    #endif
    void* (*fn)(void*);
    void* arg;
    int64_t result;
    uint32_t core_id;
} cron_fiber_t;

#if defined(_WIN32)
static unsigned __stdcall _cron_fiber_trampoline(void* raw) {
    cron_fiber_t* f = (cron_fiber_t*)raw;
    f->result = (int64_t)(intptr_t)f->fn(f->arg);
    return 0;
}
static inline cron_fiber_t* cron_spawn_raw(void* (*fn)(void*), void* arg, uint32_t core_id) {
    cron_fiber_t* f = (cron_fiber_t*)malloc(sizeof(cron_fiber_t));
    f->fn = fn;
    f->arg = arg;
    f->result = 0;
    f->core_id = core_id;
    f->thread = (HANDLE)_beginthreadex(NULL, 0, _cron_fiber_trampoline, f, 0, NULL);
    return f;
}
static inline int64_t cron_await_raw(cron_fiber_t* f) {
    if (!f) return 0;
    WaitForSingleObject(f->thread, INFINITE);
    CloseHandle(f->thread);
    int64_t res = f->result;
    free(f);
    return res;
}
#else
static void* _cron_fiber_trampoline(void* raw) {
    cron_fiber_t* f = (cron_fiber_t*)raw;
    f->result = (int64_t)(intptr_t)f->fn(f->arg);
    return NULL;
}
static inline cron_fiber_t* cron_spawn_raw(void* (*fn)(void*), void* arg, uint32_t core_id) {
    cron_fiber_t* f = (cron_fiber_t*)malloc(sizeof(cron_fiber_t));
    f->fn = fn;
    f->arg = arg;
    f->result = 0;
    f->core_id = core_id;
    pthread_create(&f->thread, NULL, _cron_fiber_trampoline, f);
    return f;
}
static inline int64_t cron_await_raw(cron_fiber_t* f) {
    if (!f) return 0;
    pthread_join(f->thread, NULL);
    int64_t res = f->result;
    free(f);
    return res;
}
#endif
#define await(f) cron_await_raw((cron_fiber_t*)(uintptr_t)(f))

