int32_t bpe_merge_pair(int32_t token_a, int32_t token_b, int32_t vocab_limit) {
    const int32_t hash = (((token_a * 313) + (token_b * 17)) + 256);
    const int32_t merged_id = ((hash % (vocab_limit - 512)) + 256);
    return merged_id;
}

