float dispatch_hard_tool(int32_t tool_id, float arg0, float arg1) {
    if ((tool_id == 101)) {
        const float diff = (arg0 - arg1);
        if ((diff < 0.0)) {
            return (0.0 - diff);
        }
        return diff;
    }
    if ((tool_id == 102)) {
        const float threshold = 0.5;
        if ((arg0 > threshold)) {
            return 1.0;
        }
        if ((arg0 < (0.0 - threshold))) {
            return -1.0;
        }
        return 0.0;
    }
    if ((tool_id == 103)) {
        const float addr_offset = (arg0 * 64.0);
        const float value = (addr_offset + arg1);
        return value;
    }
    return -999.0;
}

